/*
 * Sample data for the game-cat v1 UI prototype.
 * Not real user data. Steam app IDs and names are used to make the layout
 * legible; playtime, tags, reviews, and collection membership are invented.
 */

function game(appId, name, overrides = {}) {
  return {
    appId,
    name,
    ownership: "owned",
    installed: false,
    playtime: 0,
    lastPlayed: null,
    releaseYear: null,
    metacritic: null,
    reviewScore: null,
    reviewTier: null,
    reviewCount: 0,
    type: "game",
    platforms: ["windows"],
    developers: [],
    publishers: [],
    genres: [],
    categories: [],
    tags: [],
    steamCollections: [],
    sizeOnDisk: null,
    metadata: { tags: "ok", store: "ok", reviews: "ok" },
    ...overrides,
  };
}

